// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(uint256 depositAmount, address logAddr) public {
        vm.assume(logAddr != address(0));
        vm.assume(logAddr != address(c));
        vm.assume(depositAmount > 0);

        LogFileHelper helper = new LogFileHelper();
        c.SetLogFile(address(helper));
        c.Initialized();

        address depositor = address(0xdead);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        assertTrue(helper.GetHistoryLength() == 1);
    }
}

contract LogFileHelper {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function GetHistoryLength() public view returns (uint256) {
        return History.length;
    }
}
